:host(:not([hidden])) {
  display: flex;
  gap: calc(3 * var(--space-step));
  padding-inline: var(--calendar-dialog-row-padding-inline);
  font-size: 0.77rem;
  align-items: center;
  overflow: hidden;
  flex-wrap: nowrap;
}

.categories-list {
  padding: 0;
  margin: 0;
  list-style: none;
  display: inline-flex;
  flex-wrap: nowrap;
  flex-direction: row;
  gap: calc(3 * var(--space-step));
  flex: 0 1 auto;
  overflow: hidden;

  li {
    display: inline-block;
    padding: var(--space-step) calc(2 * var(--space-step));
    border-radius: var(--space-step);
    color: var(--item-text-color, var(--button-primary-text-color, currentColor));
    background: var(--item-color, var(--button-primary-background-color, transparent));
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
  }
}

.overflow-label {
  flex-shrink: 0;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
